SET NAMES utf8mb4;
CREATE TABLE siklus (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL, aktif TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE peran (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(60) NOT NULL, cakupan ENUM('semua','bab','tugas') NOT NULL DEFAULT 'semua', bawaan TINYINT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE hak_akses (peran_id INT NOT NULL, hak VARCHAR(40) NOT NULL, PRIMARY KEY (peran_id,hak), FOREIGN KEY (peran_id) REFERENCES peran(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE bab (id INT PRIMARY KEY, nomor INT NOT NULL, nama VARCHAR(200) NOT NULL, pj_id INT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE pengguna (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(40) NOT NULL UNIQUE, nama VARCHAR(100) NOT NULL, password_hash VARCHAR(255) NOT NULL, peran_id INT NOT NULL, atasan_id INT NULL, bab_id INT NULL, aktif TINYINT NOT NULL DEFAULT 1, gagal_login INT NOT NULL DEFAULT 0, terkunci_sampai DATETIME NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (peran_id), KEY (atasan_id), KEY (bab_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE standar (id INT AUTO_INCREMENT PRIMARY KEY, bab_id INT NOT NULL, nomor VARCHAR(10) NOT NULL UNIQUE, nama VARCHAR(255) NOT NULL, KEY (bab_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ep (id INT AUTO_INCREMENT PRIMARY KEY, standar_id INT NOT NULL, nomor VARCHAR(20) NOT NULL UNIQUE, urut INT NOT NULL DEFAULT 0, nomor_resmi VARCHAR(30) NULL, bunyi TEXT NOT NULL, bukti TEXT NULL, skor VARCHAR(20) NULL, jenis_telusur VARCHAR(60) NULL, tdd TINYINT NOT NULL DEFAULT 0, tdd_alasan VARCHAR(255) NULL, KEY (standar_id), KEY (urut)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE penugasan (ep_id INT PRIMARY KEY, anggota_id INT NOT NULL, ditugaskan_oleh INT NOT NULL, tenggat DATE NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (anggota_id), FOREIGN KEY (ep_id) REFERENCES ep(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE jenis_dokumen (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(60) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE dokumen (id INT AUTO_INCREMENT PRIMARY KEY, judul VARCHAR(200) NOT NULL, jenis_id INT NULL, pemilik_id INT NOT NULL, bab_id INT NULL, status ENUM('menunggu','terverifikasi','valid','revisi') NOT NULL DEFAULT 'menunggu', versi_aktif_id INT NULL, nomor_dokumen VARCHAR(100) NULL, berlaku_sampai DATE NULL, tinjau_ulang DATE NULL, diarsipkan TINYINT NOT NULL DEFAULT 0, verifikator_id INT NULL, verifikasi_pada DATETIME NULL, validator_id INT NULL, validasi_pada DATETIME NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (pemilik_id), KEY (bab_id), KEY (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE dokumen_versi (id INT AUTO_INCREMENT PRIMARY KEY, dokumen_id INT NOT NULL, nomor INT NOT NULL, judul VARCHAR(200) NOT NULL, file_nama VARCHAR(64) NULL, file_asli VARCHAR(255) NOT NULL, ukuran INT NOT NULL, hash CHAR(64) NOT NULL, pengunggah_id INT NOT NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, file_dihapus TINYINT NOT NULL DEFAULT 0, KEY (dokumen_id), FOREIGN KEY (dokumen_id) REFERENCES dokumen(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE dokumen_ep (dokumen_id INT NOT NULL, ep_id INT NOT NULL, ditautkan_oleh INT NOT NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, aktif TINYINT NOT NULL DEFAULT 1, PRIMARY KEY (dokumen_id,ep_id), KEY (ep_id), FOREIGN KEY (dokumen_id) REFERENCES dokumen(id) ON DELETE CASCADE, FOREIGN KEY (ep_id) REFERENCES ep(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE log (id INT AUTO_INCREMENT PRIMARY KEY, waktu DATETIME NOT NULL, pelaku_id INT NULL, pelaku_nama VARCHAR(100) NOT NULL, aksi VARCHAR(40) NOT NULL, bab_id INT NULL, ep_id INT NULL, dokumen_id INT NULL, dokumen_judul VARCHAR(200) NULL, dokumen_nomor VARCHAR(100) NULL, catatan TEXT NULL, info TEXT NULL, admin_only TINYINT NOT NULL DEFAULT 0, prev_hash CHAR(64) NOT NULL, hash CHAR(64) NOT NULL, KEY (bab_id), KEY (dokumen_id), KEY (pelaku_id), KEY (waktu)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

