ALTER TABLE pengguna ADD COLUMN berlaku_sampai DATETIME NULL;
CREATE TABLE pengaturan (kunci VARCHAR(40) PRIMARY KEY, nilai VARCHAR(255) NOT NULL DEFAULT '') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE penilaian (ep_id INT PRIMARY KEY, skor TINYINT NOT NULL, catatan VARCHAR(500) NULL, dinilai_oleh INT NOT NULL, diperbarui TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (ep_id) REFERENCES ep(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE laporan (id INT AUTO_INCREMENT PRIMARY KEY, dokumen_id INT NOT NULL, ep_id INT NULL, pelapor_id INT NOT NULL, pesan TEXT NOT NULL, status ENUM('terbuka','selesai') NOT NULL DEFAULT 'terbuka', tanggapan TEXT NULL, ditangani_oleh INT NULL, ditangani_pada DATETIME NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (dokumen_id), KEY (status), FOREIGN KEY (dokumen_id) REFERENCES dokumen(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE komentar (id INT AUTO_INCREMENT PRIMARY KEY, dokumen_id INT NOT NULL, pengirim_id INT NOT NULL, isi TEXT NOT NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY (dokumen_id), KEY (dibuat), FOREIGN KEY (dokumen_id) REFERENCES dokumen(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE temuan (id INT AUTO_INCREMENT PRIMARY KEY, bab_id INT NOT NULL, ep_id INT NULL, sumber ENUM('audit_internal','simulasi','surveior','lainnya') NOT NULL DEFAULT 'audit_internal', uraian TEXT NOT NULL, pic_id INT NULL, tenggat DATE NULL, status ENUM('terbuka','dikerjakan','selesai','ditutup') NOT NULL DEFAULT 'terbuka', tindak_lanjut TEXT NULL, dibuat_oleh INT NOT NULL, dibuat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, selesai_pada DATETIME NULL, ditutup_oleh INT NULL, ditutup_pada DATETIME NULL, KEY (bab_id), KEY (pic_id), KEY (status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
